describe('Restore Archived Record Functionality', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should successfully restore an archived record to active status', () => {
    // Intercept the API call to restore the record
    cy.intercept('POST', '/api/records/*/restore').as('restoreRecord');

    // Navigate to the records list
    cy.get('[data-testid="records-list"]').should('be.visible');

    // Find the archived record and click the restore button
    cy.get('[data-testid="record-row-123"]').should('be.visible');
    cy.get('[data-testid="restore-button-123"]').should('contain', 'Restore').click();

    // Wait for the API call to complete
    cy.wait('@restoreRecord').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify success message appears
    cy.get('[data-testid="success-toast"]').should('be.visible');
    cy.get('[data-testid="success-toast"]').should('contain', 'Record restored successfully');

    // Verify the record is no longer in archived state
    cy.get('[data-testid="record-row-123"]').should('contain', 'Active');
    cy.get('[data-testid="archived-badge-123"]').should('not.exist');

    // Verify the restore button is replaced with edit/delete options
    cy.get('[data-testid="edit-button-123"]').should('be.visible');
    cy.get('[data-testid="restore-button-123"]').should('not.exist');
  });

  it('should handle error when restoring an archived record', () => {
    // Intercept the API call and mock a server error
    cy.intercept('POST', '/api/records/*/restore', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('restoreRecordError');

    // Navigate to the records list
    cy.get('[data-testid="records-list"]').should('be.visible');

    // Find the archived record and click the restore button
    cy.get('[data-testid="record-row-456"]').should('be.visible');
    cy.get('[data-testid="restore-button-456"]').should('contain', 'Restore').click();

    // Wait for the failed API call
    cy.wait('@restoreRecordError');

    // Verify error message appears
    cy.get('[data-testid="error-toast"]').should('be.visible');
    cy.get('[data-testid="error-toast"]').should('contain', 'Failed to restore record');

    // Verify the record remains in archived state
    cy.get('[data-testid="record-row-456"]').should('contain', 'Archived');
    cy.get('[data-testid="archived-badge-456"]').should('be.visible');

    // Verify the restore button is still available
    cy.get('[data-testid="restore-button-456"]').should('be.visible');
  });
});
